import { headers } from 'next/headers';

async function logAnalytics(data: { url: string; userAgent: string }) {
  await new Promise((resolve) => setTimeout(resolve, 100));
  console.log('[Analytics] Page view logged:', data);
}

export default async function Home() {
  const headerStore = headers();
  const [url, userAgent] = [headerStore.get('x-url'), headerStore.get('user-agent')];

  logAnalytics({
    url: url || '/',
    userAgent: userAgent || 'unknown',
  }).catch(console.error);

  return (
    <main>
      <h1>Welcome</h1>
      <p>Please implement page view logging that doesn&apos;t block the response.</p>
    </main>
  );
}

